import base64

_SRC = ""


def apply():
    import sys
    L = sys.modules.get('moduli.libreria')
    if L is None:
        try:
            import moduli.libreria as L  # noqa
        except Exception:
            print('[SCAL111] libreria non presente (ok)')
            return False
    C = getattr(L, 'LibreriaSlider', None)
    if C is None:
        return True
    try:
        src = base64.b64decode(_SRC).decode('utf-8')
        g = L.__dict__
        exec(compile(src, 'scaletta_sync_111', 'exec'), g)
        C.apri_dialog_cantanti = g['apri_dialog_cantanti']
        C.salva_righe = g['salva_righe']
        print('[SCAL111] SYNC direzionale (pull se vuota / push se piena) + percorso ricaricati a caldo')
        return True
    except Exception as e:
        print('[SCAL111] errore:', e)
        return False


try:
    apply()
except Exception as _e:
    print('patch 111: %s' % _e)
